// Table lookup only. Streams and rules come from config.
const cfg = $('Config').first().json;
const src = $('Pop Intake Item').item.json.item;
const full = `${src.repository_owner}/${src.repository_name}`;
const globToRe = g => new RegExp('^' + String(g).split('*').map(s => s.replace(/[.+?^${}()|[\]\\]/g, '\\$&')).join('.*') + '$');
let stream = null;
for (const r of ((cfg.streams && cfg.streams.rules) || [])) { if (r && r.repo && globToRe(r.repo).test(full)) { stream = r.stream; break; } }
if (!stream) stream = (cfg.streams && cfg.streams.default) || null;
if (!stream) throw new Error(`sorter: no stream for ${full} and no default stream in config`);
const item = Object.assign({}, src, { stream });
return { json: { stream, list: cfg.queues.stream_prefix + stream, key: `${full}#${src.issue_number}`, payload: JSON.stringify(item) } };

// A seen issue with no hold label may proceed to the build queue; if its repository is one the runner never builds, it is claimed once and the ticket is told the operator builds it.
const cfg = $('Config').first().json;
const src = $('Pop Intake Item').item.json.item;
const labels = (src.labels || []).map(l => typeof l === 'string' ? l : (l && l.name) || '');
const isPR = /\/pull\/\d+/.test(String(src.issue_url || ''));
const held = labels.includes(cfg.labels.hold);
const full = `${src.repository_owner}/${src.repository_name}`;
const skipped = ((cfg.build && cfg.build.skip_repos) || []).includes(full);
const key = `${full}#${src.issue_number}`;
return { json: { key, eligible: !held && !isPR, held, isPR, skipped } };

