return { json: { stream, list: cfg.queues.build_prefix + stream, key: `${full}#${src.issue_number}`, payload: JSON.stringify(item) } };

// Head-of-chain rule. Primary: the dependencies API (blocked_by). Fallback: body lines '<blocked_by_line> #N'.
const cfg = $('Config').first().json;
const src = $('Pop Intake Item').item.json.item;
const resp = $input.first().json;
const status = Number(resp.statusCode || 0);
const body = resp.body;
if (status >= 200 && status < 300 && Array.isArray(body)) {
  const open = body.filter(b => b && b.state === 'open').map(b => b.number);
  return [{ json: { source: 'api', open_blockers: open, refs: [], head: open.length === 0 } }];
}
const marker = String((cfg.chain && cfg.chain.blocked_by_line) || 'Blocked by:');
const re = new RegExp(marker.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*#(\\d+)', 'gi');
const refs = []; let m; while ((m = re.exec(String(src.body || '')))) refs.push(Number(m[1]));
return [{ json: { source: 'body', open_blockers: [], refs, head: refs.length === 0 } }];

// Triage works on issue tickets only. Three kinds of item exist:
//  - an issue ticket (URL is .../issues/N): triaged, then released to build when approved;
//  - feedback / repair (review comments or failing checks on a pipeline PR) and pipeline-repair (a failed build run): their own paths, no triage;
//  - anything else: dropped.
const cfg = $('Config').first().json;
const it = $json.item || {};
const isFeedback = it.stage === 'feedback' || it.stage === 'repair';
const isRepair = it.stage === 'repair';
const isPipelineRepair = it.stage === 'pipeline-repair';
const isIssue = !isFeedback && !isPipelineRepair && /\/issues\/\d+$/.test(String(it.issue_url || '')) && Number(it.issue_number) > 0;
const prc = cfg.pipeline_repair || {};
const labels = (it.labels || []).map(l => typeof l === 'string' ? l : (l && l.name) || '');
const specPresent = isIssue && !!cfg.labels.spec_present && labels.includes(cfg.labels.spec_present);
const key = `${it.repository_owner}/${it.repository_name}#${it.issue_number}`;
const prKey = `${it.repository_owner}/${it.repository_name}#${it.pr_number || ''}`;
const claimPrefix = isRepair ? cfg.repair.claim_prefix : cfg.feedback.claim_prefix;
return { json: { item: it, key, isFeedback, isRepair, isPipelineRepair, isIssue, drop: !(isIssue || isFeedback || isPipelineRepair), specPresent, seen_key: cfg.keys.seen_prefix + key, spec_key: cfg.keys.spec_prefix + key, feedback_claim: isFeedback ? `${claimPrefix}${key}@${it.feedback_id || ''}` : '', attempts_key: isRepair ? `${cfg.repair.attempts_prefix}${prKey}` : '', max_attempts: Number((cfg.repair && cfg.repair.max_attempts) || 3),
  pipeline_claim: isPipelineRepair ? String(prc.claim_prefix || 'pipeline-repair:') + String(it.run_id || '') : '', pipeline_day_key: isPipelineRepair ? String(prc.daily_prefix || 'pipeline-repair-day:') + new Date().toISOString().slice(0, 10) : '', pipeline_max: Number(prc.max_per_day || 5), pipeline_blocked: prc.enabled === false || String(it.target_mode || '') === 'pipeline-repair' || !it.run_id } };

