// Restoration: the failed run was a ticket build, so the ticket is released to build again with the branch it left behind.
const cfg = $('Config').first().json;
const src = $('Pop Intake Item').item.json.item;
if (String(src.target_mode || '') !== 'build' || !(Number(src.target_issue) > 0) || !src.target_repo) return [];
const [owner, name] = String(src.target_repo).split('/');
const full = `${owner}/${name}`;
const globToRe = g => new RegExp('^' + String(g).split('*').map(s => s.replace(/[.+?^${}()|[\]\\]/g, '\\$&')).join('.*') + '$');
let stream = null;
for (const r of ((cfg.streams && cfg.streams.rules) || [])) { if (r && r.repo && globToRe(r.repo).test(full)) { stream = r.stream; break; } }
if (!stream) stream = (cfg.streams && cfg.streams.default) || null;
if (!stream) return [];
const key = `${full}#${src.target_issue}`;
const item = { delivery_id: 'restore:' + src.run_id, repository_owner: owner, repository_name: name, issue_number: Number(src.target_issue), stage: 'build', restoration: true, failed_run_url: src.run_url, title: src.run_title, body: '', labels: [], author: '', issue_url: `https://github.com/${full}/issues/${src.target_issue}`, stream };
return { json: { key, owner, name, issue: Number(src.target_issue), attempts_key: String(cfg.keys.build_attempts_prefix || 'build-attempts:') + key, max_attempts: Number((cfg.build || {}).max_attempts || 1), hold: cfg.labels.hold, needs_triage: cfg.labels.needs_triage, list: cfg.queues.build_prefix + stream, payload: JSON.stringify(item) } };
